// === Tab: mySketch.js ===
/*
It is a 3D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Balls".

It's just a group of dancing balls on a dance floor. I couldn't
resist adding different camera motions and stylized post-effects.

The beat of the animation is at 148 bpm. A quick YT search
revealed this playlist of suitable songs:

https://youtube.com/playlist?list=PLs-loPKWtc8yipS_Uk0MnjOkfhCUboUjo&

I formatted the shader code using (CTRL/COMMAND)+B. The result
wasn’t executable. I then corrected everything that wasn’t working
(the #defines get formatted, and that can have disastrous
consequences, as shown here). So I probably won’t be doing that
again any time soon ;-)

Interaction:
- Space Bar: Pause/Play
- Mouse Wheel: Forward / Backward in time

*/

const scale = Math.max(1, devicePixelRatio)
let theShader, wheelDelta = 0, wheelOffset = 0, pause = false, paused = 0, time = 0

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2968872/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
	createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
	resizeCanvas(windowWidth, windowHeight)
}

function mouseWheel(e) {
	if (wheelDelta * e.deltaY < 0) {
		wheelDelta = e.deltaY
	} else {
		wheelDelta = lerp(wheelDelta, e.deltaY, .05)
	}
	wheelOffset += wheelDelta
}

function keyPressed(e) {
	if (e.key === " ") {
		if (!pause) {
			pause = true
		} else {
			pause = false
			paused = millis() - time
		}
	}
}

function draw() {
  shader(theShader)
  if (!pause) time = millis() - paused
  theShader.setUniform("resolution", [width * scale, height * scale])
  theShader.setUniform("wheel", [wheelDelta, wheelOffset])
  theShader.setUniform("time", time / 1000.0)
  rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
 * made by Matthias Hurrle (@atzedent)
 */
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
uniform vec2 wheel;
#define FC gl_FragCoord.xy
#define R resolution
#define TT (time + wheel.y / 1e3)
#define T (284. + TT * mix(1., .5, step(.75, curve(TT * .01, .04))))
#define S smoothstep
#define N normalize
#define MN min(R.x, R.y)
#define MX max(R.x, R.y)
#define TAU 6.2831853
#define ESN 1.5707963
#define PI 3.14159265
#define BEAT (T * (148. / (TAU + PI))) // modify the number according to the bpm of your song
#define LP vec3(0, 9, 8) // light position in world space
#define syl(p, s) (length(p) - s)
#define rot(a) mat2(cos((a) - vec4(0, 11, 33, 0)))
#define rnd(a) fract(sin(a * 12.599) * 78.233) // // 1D pseudo-random from scalar input
#define tween easeInOutExpo
// Cosine palette: returns a smooth RGB color cycle for scalar k
vec3 palette(float k) {
	vec3
	a = vec3(.75, .5, .5),
	b = vec3(.5, .5, .75),
	c = vec3(1, 1.8, 1),
	d = vec3(.2, .4, .8);

	return a + b * cos(TAU * (c * k + d));
}
// Smooth random curve over time:
// - splits time into integer segments
// - interpolates random values with eased interpolation
float curve(float t, float e) {
	t /= e;

	return mix(
		rnd(floor(t)),
		rnd(floor(t) + 1.),
		pow(S(.0, 1., fract(t)), e)
	);
}
// Signed distance field (SDF) of a box
float box(vec3 p, vec3 s) {
	p = abs(p) - s;

	return max(max(p.x, p.y), p.z);
}
// Exponential ease in/out used for camera rhythm
float easeInOutExpo(float t) {
	if (t == .0 || t == 1.) {
		return t;
	}
	if ((t *= 2.) < 1.) {
		return .5 * pow(2., 10. * (t - 1.));
	} else {
		return .5 * (-pow(2., -10. * (t - 1.)) + 2.);
	}
}
// Defines the scene
// returns vec2(distance, materialId)
// materialId 0 = room, 1 = balls
vec2 map(vec3 p) {
	const float n = 4.5;
	// beat-driven scalar used for the spheres' deformation
	float b = pow(S(.0, 1., sin(BEAT) * .5 + .5), .5);
	vec3 q = p;
	q *= 1. + vec3(-.1, .1, -.1) * (.5 * sin(-BEAT) + .5);
	q.z += b / 5.;
	q.xz = q.xz - n * clamp(round(q.xz / n), -1., 1.);
	q.y -= b * .2 - .175;
	vec2
	room = vec2(-box(p + vec3(0, -9, 0), vec3(90, 10, 90)), 0),
	ball = vec2(syl(q, 1.), 1);

	return room.x < ball.x ? room : ball;
}
// Calculates the normal of the surface at point p
vec3 norm(vec3 p) {
	float h = 1e-3;
	vec2 k = vec2(-1, 1);

	return N(
		k.xyy * map(p + k.xyy * h).x +
		k.yxy * map(p + k.yxy * h).x +
		k.yyx * map(p + k.yyx * h).x +
		k.xxx * map(p + k.xxx * h).x
	);
}
// Very cheap AO probe
float getao(vec3 p, vec3 n, float dist) {
	return clamp(map(p + n * dist).x / dist, .0, 1.);
}
// Camera animation
void cam(inout vec3 p) {
	float t = T * .05, f = curve(t, .04);
	p.yz *= rot(.45 + sin(T * .5) * .3);
	p.xz *= rot(10. + tween(sin(BEAT * .005)) * (TAU + f));
	p.xy *= rot(sin(.15 + t + f * .2) * .25);
}
// Raymarching and shading of the scene
vec3 render(vec2 uv) {
	float pr = min(2., MX / MN), chf = curve(T * .01, .04);

	vec3
	col = vec3(0),
	// animated camera origin
	ro = vec3(0, 0, exp(-cos(1.25 - T * (.5 + chf))) - (7.8 - chf)) * pr,
	rd = N(vec3(uv, pr));

	cam(ro);
	cam(rd);

	vec3
	p = ro,
	// time and beat-varying palette
	pal = palette(T + floor(BEAT) + pow(S(.0, .1, fract(BEAT)), 10.));

	const float steps = 400., maxd = 400.;

	float dd = .0;
	vec2 o = vec2(0);
	for (float i = .0; i < steps; i++) {
		o = map(p);
		float d = o.x * .8;

		if (d < 1e-3) {
			// floor tiles
			if (o.y == .0) {
				vec2 g = abs(fract(p.xz * .25) - .5) * 2.;
				col += pal * (mix(.25, .0, step(.5, chf)) - step(min(g.x, g.y), .04)); // grid lines
			}
			break;
		}
		if (dd > maxd) {
			dd = maxd;
			break;
		}

		p += rd * d;
		dd += d;
	}

	vec3 l = N(LP - p), n = norm(p);

	float
	diff = clamp(dot(n, l), .0, 1.), fres = 1. - clamp(dot(rd, l), .0, 1.),
	spec = max(.0, dot(n, N(LP - rd))), ao = getao(p, l, .5);

	col += diff * ao * mix(pal, vec3((pal.x + pal.y + pal.z) / 3.), step(.7, chf)) * 2.;
	col += fres * spec * spec;

	// pulsing rings
	float d = pow(S(1., .0, length(uv * 1.2)), .5 + (sin(BEAT) * .5 + .5)) + .125;
	d = sin(d * dot(col, col)) - .85;
	d = abs(d);
	d = max(1., 1. / d);

	// final grading/falloff
	col *= d * mix(1., o.y, step(.9, chf));
	col *= S(.0, 1., exp(-5e-4 * dd * dd * dd)); // distance fog
	col = exp(-col * .7); // tone mapping / soft compression

	return col;
}
// Entrypoint of the shader
void main() {
	vec2 uv = (FC - .5 * R) / MN;
	vec3 col = render(uv);
	O = vec4(col, 1);
}

